package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.ProductDAO; import com.example.ecommerce.model.*; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException; import java.math.BigDecimal; import java.util.*;
@WebServlet("/cart") public class CartServlet extends HttpServlet{
 @SuppressWarnings("unchecked") private List<CartItem> cart(HttpSession s){List<CartItem> c=(List<CartItem>)s.getAttribute("cart"); if(c==null){c=new ArrayList<>();s.setAttribute("cart",c);} return c;}
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{List<CartItem> c=cart(req.getSession());BigDecimal total=c.stream().map(CartItem::getSubtotal).reduce(BigDecimal.ZERO,BigDecimal::add);req.setAttribute("total",total);req.getRequestDispatcher("/WEB-INF/views/cart.jsp").forward(req,resp);} 
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String action=req.getParameter("action");List<CartItem> c=cart(req.getSession());int productId=Integer.parseInt(req.getParameter("productId"));if("remove".equals(action)){c.removeIf(i->i.getProduct().getId()==productId);}else{Product p=new ProductDAO().findById(productId);int qty=Integer.parseInt(req.getParameter("quantity")==null?"1":req.getParameter("quantity"));if(qty<1)qty=1;if(qty>p.getStock())qty=p.getStock();boolean found=false;for(CartItem i:c){if(i.getProduct().getId()==productId){i.setQuantity(Math.min(qty,p.getStock()));found=true;}}if(!found && p.getStock()>0)c.add(new CartItem(p,qty));}resp.sendRedirect(req.getContextPath()+"/cart");}catch(Exception e){throw new ServletException(e);}}
}
